这个设计挑战很有意思。让我先深入分析文档中64卦的坐标映射，然后设计这个函数。

## 分析

### 文档中的关键设计

**三维坐标映射：**
```
T[时间][空间][关系] → 64个单元格
时间: 沉寂(0) → 稳定(1) → 活跃(2) → 爆发(3)
空间: 单平台(0) → 少平台(1) → 多平台(2) → 跨域(3)
关系: 孤立(0) → 初连(1) → 网络(2) → 生态(3)
```

**核心思想：**
- 从潜藏（坤 T[0][0][0]）到爆发（乾 T[3][3][3]）是势能积累与释放的完整周期
- 64卦不是分类标签，而是描述事物在不同阶段的能量状态

### 物极必反的数学模型

基于太极思想：`阳极生阴，阴极生阳`

```
生长期: E(t) 递增 → 达到顶峰(T[3][3][3]) → 物极必反 → 衰退期开始
衰退期: E(t) 递减 → 回归沉寂(T[0][0][0]) → 完成一个完整周期
```

现在设计具体的势能函数：

---

## 生长-衰退势能函数设计

### 核心公式

```javascript
/**
 * ECHO 势能函数
 * 反映资产在使用过程中的生命周期生长与衰退
 * 
 * @param {Object} coords - 三维坐标 {t: 0-3, s: 0-3, r: 0-3}
 * @param {Object} momentum - 动量 {dT, dS, dR} 变化梯度
 * @param {number} phase - 阶段: 0=生长期, 1=顶峰物极必反, 2=衰退期
 * @returns {number} 势能值 0-100
 */
function calculateShiEnergy(coords, momentum, phase) {
  const { t, s, r } = coords;
  const { dT, dS, dR } = momentum;

  // ========== 阶段1: 生长期 ==========
  if (phase === 0) {
    // 基础势能 = 三维坐标的加权和
    const baseEnergy = (t * 25) + (s * 25) + (r * 25) + 5;

    // 动量加速：当坐标正在上升时，势能额外增强
    const momentumBoost = (dT + dS + dR) * 5;

    // S型生长曲线：初期慢增长，中期爆发，后期趋近顶峰
    const sCurve = 1 / (1 + Math.exp(-(baseEnergy - 50) * 0.1));

    const growingEnergy = (baseEnergy + momentumBoost) * sCurve;

    // 物极必反阈值检测
    if (t === 3 && s === 3 && r === 3 && momentumBoost > 10) {
      return {
        energy: Math.min(100, growingEnergy),
        trigger: '物极必反',
        nextPhase: 1
      };
    }

    return {
      energy: Math.min(100, growingEnergy),
      phase: '生长期',
      gradient: momentumBoost
    };
  }

  // ========== 阶段2: 顶峰物极必反 ==========
  if (phase === 1) {
    // 顶峰状态：三维全满(3,3,3)触发阴阳转换
    const yangPeak = (t === 3 && s === 3 && r === 3);

    if (yangPeak) {
      // 太极转换：阳极生阴
      const instability = Math.random() * 10 + 5; // 5-15%的波动
      return {
        energy: 100 - instability,
        trigger: '乾卦顶峰 → 阴阳转换',
        nextPhase: 2,
        yinYangShift: -instability // 阴气初生
      };
    }
  }

  // ========== 阶段3: 衰退期 ==========
  if (phase === 2) {
    // 衰退势能 = 顶峰势能 * 衰退系数 * 卦象阴阳属性
    const yangPhase = [3, 14, 23, 34]; // 典型的阳卦（可扩展）

    // 计算衰退速率：基于当前势能和卦象属性
    // 阴卦衰退慢（-2%），阳卦衰退快（-5%）
    const isYangHexagram = isYangHex(coords); 
    const decayRate = isYangHexagram ? 0.05 : 0.02;

    // 六爻位置影响：上九（最高爻）代表成熟顶峰，开始衰退
    // 初九代表新生，还有生长空间
    const yaoPosition = calculateYaoPosition(coords); // 0-5
    const yaoDecayMultiplier = yaoPosition < 3 ? 0.8 : 1.2; // 上爻衰退更快

    // 衰退公式：E(t) = E₀ * e^(-λt)
    const currentEnergy = momentum.currentEnergy || 100;
    const decayCoefficient = decayRate * yaoDecayMultiplier;
    const decayedEnergy = currentEnergy * Math.exp(-decayCoefficient);

    // 64卦衰退映射：每个卦象对应特定的衰退强度
    const decayStrength = getDecayStrengthFromHexagram(coords);

    return {
      energy: Math.max(0, decayedEnergy * (1 - decayStrength)),
      phase: '衰退期',
      decayRate: decayCoefficient,
      hexagramDecay: decayStrength,
      yaoPosition: yaoPosition
    };
  }

  return { energy: 0, phase: '沉寂' };
}

/**
 * 六爻位置计算
 * 初九=0（新生/潜藏）→ 二九→ 三九 → 四九 → 五九 → 上九=5（顶峰/爆发）
 */
function calculateYaoPosition(coords) {
  return coords.t + coords.s + coords.r; // 简单加和映射到0-9，再归一化
}

/**
 * 卦象阴阳属性判断
 * 阳卦：1,3,5爻为阳（奇数位置）
 * 简化判断：空间维度为主判断阴阳
 */
function isYangHex(coords) {
  // 简化的阴阳判断：空间维度为阳（外显/扩展）
  return coords.s >= 2; 
}

/**
 * 获取64卦对应的衰退强度系数
 * 
 * 设计原理：
 * - 乾卦(111): 完全阳，刚健极度，衰退最快
 * - 坤卦(000): 完全阴，柔顺至极，衰退最慢
 * - 其他卦象根据六爻阴阳分布决定衰退速率
 */
function getDecayStrengthFromHexagram(coords) {
  const [t, s, r] = [coords.t, coords.s, coords.r];

  // 将三维坐标转换为二进制卦象 (6位)
  // t: 2bits, s: 2bits, r: 2bits
  const hexagram = (t << 4) | (s << 2) | r; // 0-63

  // 乾卦 (63): 111111 - 纯阳，衰退系数最高
  if (hexagram === 63) return 0.15;

  // 坤卦 (0): 000000 - 纯阴，衰退系数最低
  if (hexagram === 0) return 0.02;

  // 计算卦象中阳爻的数量
  const binary = hexagram.toString(2).padStart(6, '0');
  const yangCount = (binary.match(/1/g) || []).length;

  // 阳爻越多，衰退越快
  const yangDecay = (yangCount / 6) * 0.12;

  // 特定卦象的特殊处理
  const specialHexagrams = {
    30: 0.12, // 离卦（火）：光明但不稳定，衰退较快
    29: 0.10, // 坎卦（水）：陷落，重生慢
    52: 0.03, // 艮卦（山）：停止，休眠状态
    57: 0.08, // 巽卦（风）：渗透，缓慢衰退
    // ... 可扩展更多卦象
  };

  return specialHexagrams[hexagram] || (yangDecay + 0.03);
}
```

