### 完整的生命周期状态机

```javascript
/**
 * 资产生命周期状态机
 * 模拟：生长期 → 顶峰物极必反 → 衰退期 → (可能)重生
 */
class AssetLifecycle {
  constructor(initialCoords = {t: 0, s: 0, r: 0}) {
    this.coords = initialCoords;
    this.phase = '生长期';
    this.phaseHistory = [];
    this.energyHistory = [];
  }

  // 主更新函数
  update(usageMetrics) {
    // 1. 根据使用数据更新三维坐标
    this.coords = this.calculateNewCoords(usageMetrics);

    // 2. 计算当前势能
    const momentum = this.calculateMomentum();
    const result = calculateShiEnergy(this.coords, momentum, this.getPhaseCode());

    // 3. 状态转换检测
    this.detectPhaseTransition(result);

    // 4. 记录历史
    this.energyHistory.push(result.energy);
    this.phaseHistory.push(this.phase);

    return {
      ...result,
      coords: this.coords,
      phase: this.phase,
      lifecycle: this.getLifecycleProgress()
    };
  }

  // 坐标计算
  calculateNewCoords(metrics) {
    const { usageCount, platformCount, referenceCount } = metrics;

    return {
      t: this.percentileToLevel(usageCount, [3, 10, 50]),      // 时间维度
      s: this.percentileToLevel(platformCount, [1, 3, 7]),     // 空间维度
      r: this.percentileToLevel(referenceCount, [0, 5, 20])    // 关系维度
    };
  }

  percentileToLevel(value, thresholds) {
    if (value < thresholds[0]) return 0;
    if (value < thresholds[1]) return 1;
    if (value < thresholds[2]) return 2;
    return 3;
  }

  // 物极必反检测
  detectPhaseTransition(result) {
    // 生长期 → 顶峰
    if (this.phase === '生长期' && result.trigger === '物极必反') {
      this.phase = '顶峰物极必反';
    }
    // 顶峰 → 衰退期
    else if (this.phase === '顶峰物极必反') {
      this.phase = '衰退期';
    }
    // 衰退期 → 可能沉寂或重生
    else if (this.phase === '衰退期' && result.energy < 5) {
      this.phase = '沉寂/潜在重生';
    }
  }

  getPhaseCode() {
    const phaseMap = {
      '生长期': 0,
      '顶峰物极必反': 1,
      '衰退期': 2,
      '沉寂': 3
    };
    return phaseMap[this.phase] || 0;
  }

  getLifecycleProgress() {
    // 返回生命周期进度百分比
    const currentEnergy = this.energyHistory[this.energyHistory.length - 1] || 0;
    if (this.phase === '生长期') {
      return (currentEnergy / 100) * 50; // 前半生
    } else if (this.phase === '顶峰物极必反') {
      return 50; // 中点
    } else if (this.phase === '衰退期') {
      return 50 + ((100 - currentEnergy) / 100) * 50; // 后半生
    }
    return 100;
  }
}
```

