### 四、核心融合公式

```javascript
/**
 * 融合公式：太极阴阳 × 四权配置
 * 
 * 实际生效势能 = f(创作者意图, 物理法则, 阴阳状态)
 */

function calculateEffectiveShiEnergy(
  coords,           // 三维坐标 T[时间][空间][关系]
  fourRights,       // {yong, yan, kuo, yi} 四权配置
  yinYangState      // {yang, yin, phase} 阴阳状态
) {
  // 1. 基础势能 = 三维坐标加权和
  const baseEnergy = (coords.t + coords.s + coords.r) * (100/9);

  // 2. 四权释放系数
  //    阳气足时，四权全开；阴气足时，四权收缩
  const rightsOpenness = (fourRights.yong + fourRights.yan + 
                          fourRights.kuo + fourRights.yi) / 20; // 0-1

  // 3. 阴阳调节因子
  //    阴气主导时抑制释放（保命），阳气主导时加速释放（扩张）
  const yinYangFactor = yinYangState.yang - yinYangState.yin;
  //    值域: -1 (全阴) ~ 0 (平衡) ~ +1 (全阳)

  // 4. 融合计算
  const yangPhase = yinYangState.phase === '顶峰物极' || 
                    yinYangState.phase === '衰退期';

  let effectiveEnergy;
  if (yangPhase) {
    // 物极必反阶段：阴阳转换，抑制过载
    // 阴气开始压制阳气，四权受限
    effectiveEnergy = baseEnergy * rightsOpenness * (1 - yinYangFactor * 0.3);
  } else {
    // 生长期：阴阳相生，协同放大
    effectiveEnergy = baseEnergy * rightsOpenness * (1 + yinYangFactor * 0.5);
  }

  return {
    energy: Math.min(100, Math.max(0, effectiveEnergy)),
    yangRatio: yinYangState.yang,
    warning: yinYangState.yang > 0.9 ? '阳气过盛，物极必反预警' : null
  };
}
```

