### 六、完整的太极轮转状态机

```javascript
class TaijiShiLifecycle {
  constructor(coords) {
    this.coords = coords; // T[时间][空间][关系]
    this.yang = this.calculateYang();
    this.phase = this.determinePhase();
  }

  calculateYang() {
    // 阴阳计算：T+S+R的和转换为阴阳比例
    const sum = this.coords.t + this.coords.s + this.coords.r;
    return {
      yang: sum / 9,           // 0-1
      yin: 1 - (sum / 9),      // 0-1
      phase: this.determinePhase(sum)
    };
  }

  determinePhase(sum) {
    if (sum <= 1) return '潜藏';      // 阴气主导
    if (sum <= 4) return '成长';      // 阴中生阳
    if (sum <= 7) return '成熟';      // 阴阳平衡
    if (sum <= 8) return '顶峰';      // 阳气鼎盛
    if (sum === 9) return '物极必反'; // 阳极生阴
    return '衰退';
  }

  // 物极必反触发
  triggerYiJiBiFan() {
    if (this.phase === '物极必反') {
      return {
        action: '强制收敛',
        changes: {
          rightsOpenness: -0.3,  // 四权收缩30%
          energyAccumulation: -0.2,  // 蓄能减少
        },
        reason: '阳极生阴，生态保护'
      };
    }
  }

  // 阴阳轮转的完整周期
  getCycle() {
    return {
      阶段: ['潜藏→成长→成熟→顶峰→物极必反→衰退→沉寂→潜藏'],
      循环: '太极无限轮转',
      四权: '随阴阳消长自动调节',
      终点: '又是起点'
    };
  }
}
```

