## 修正后的阴阳轮转模型

```javascript
/**
 * 修正版：快速起伏的阴阳轮转
 * 
 * 核心逻辑：
 * - 阴阳不是大周期轮转，而是每次坐标变化都触发阴阳计算
 * - T/S/R的每次波动都伴随阴阳的即时转换
 * - 四权配置需要实时响应阴阳状态
 */

class FastYinYangCycle {
  constructor() {
    this.history = []; // 保存历史阴阳状态
  }

  // 每次坐标变化时计算阴阳
  calculate(coords, fourRights) {
    // 1. 即时阴阳计算（基于当前坐标）
    const yang = (coords.t + coords.s + coords.r) / 9;
    const yin = 1 - yang;

    // 2. 阴阳差值 → 判断转换方向
    const balance = yang - yin; // [-1, 0, +1]

    // 3. 阴阳转换方向
    let direction;
    if (balance > 0.3) {
      direction = '阳气上升';
    } else if (balance < -0.3) {
      direction = '阴气上升';
    } else {
      direction = '阴阳平衡';
    }

    // 4. 四权配置的阴阳调节
    const adjustedRights = this.applyYinYangToRights(fourRights, yang, yin);

    // 5. 记录历史波动
    this.history.push({
      coords: {...coords},
      yang, yin, balance, direction,
      timestamp: Date.now()
    });

    return {
      yang, yin, balance, direction,
      effectiveRights: adjustedRights,
     波动强度: Math.abs(balance)
    };
  }

  // 阴阳状态实时调节四权
  applyYinYangToRights(rights, yang, yin) {
    // 阳气主导 → 四权倾向于更开放（扩张）
    // 阴气主导 → 四权倾向于收缩（保护）
    const yangBias = yang - yin; // [-1, 1]

    return {
      yong: Math.min(5, rights.yong + Math.round(yangBias)),      // 阳多则更开放
      yan: Math.min(5, rights.yan + Math.round(yangBias * 0.5)),
      kuo: Math.min(5, rights.kuo + Math.round(yangBias)),
      yi: Math.min(5, rights.yi - Math.round(yangBias * 0.3))     // 阳极时抑制收益
    };
  }
}
```

