```javascript
function checkYiJiBiFan(yang, yin, threshold = 0.8) {
  const imbalance = Math.abs(yang - yin);

  if (imbalance >= threshold) {
    return {
      triggered: true,
      type: yang > yin ? '阳极生阴' : '阴极生阳',
      adjustment: yang > yin ? -0.2 : 0.2, // 强制平衡
      reason: '阴阳失衡超过阈值'
    };
  }
  return { triggered: false };
}
